type LruState {
  vals: Map[Str, Str],
  order: List[Str],
}

fn touch(order: List[Str], key: Str) -> List[Str] {
  return order.filter(fn(k) => k != key).push(key)
}

fn evict_oldest(c: LruState) -> LruState {
  let oldest = c.order.first().unwrap_or("")
  return LruState { vals: c.vals.remove(oldest), order: c.order.drop(1) }
}

fn put_key(c: LruState, capacity: Int, key: Str, value: Str) -> LruState {
  if capacity <= 0 {
    return c
  }
  if c.vals.has(key) {
    return LruState { vals: c.vals.set(key, value), order: touch(c.order, key) }
  }
  let base = match c.vals.len() >= capacity {
    true => evict_oldest(c),
    false => c,
  }
  return LruState { vals: base.vals.set(key, value), order: base.order.push(key) }
}

pub fn lru(capacity: Int, ops: List[Str]) -> List[Str] {
  let empty_vals: Map[Str, Str] = Map {}
  let no_order: List[Str] = []
  var c = LruState { vals: empty_vals, order: no_order }
  var out: List[Str] = []
  for op in ops {
    let parts = op.split(" ")
    if parts.get_or(0, "") == "put" {
